private static void solve() {
    int[] dp = new int[500001];
    int n = sc.nextInt(), d = sc.nextInt();
    int max_length = 0;
    for (int i = 0; i < n; i++) {
        int a = sc.nextInt();
        int val = 0;
        for (int j = Math.max(0, a - d); j <= Math.min(500000, a + d); j++) {
            val = Math.max(val, dp[j]);
        }
        val += 1;
        dp[a] = val;
        max_length = Math.max(val, max_length);
    }
    out.println(max_length);
}
